// Drives the sample tutorial through every block with real app events (no tour internals touched).
const T = (c) => c.evaluate(`return document.querySelector(".dg-tutorial-card")?.firstElementChild?.textContent ?? null;`);
const waitTitle = (c, t) => c.waitFor(`document.querySelector(".dg-tutorial-card")?.firstElementChild?.textContent === ${JSON.stringify(t)}`, { label: t, timeoutMs: 6000 });
const next = (c) => c.evaluate(`[...document.querySelectorAll(".dg-tutorial-card button")].find((b) => b.textContent === "Next")?.click(); return true;`);
const cmdP = (c) => c.key({ key: "p", code: "KeyP", windowsVirtualKeyCode: 80, nativeVirtualKeyCode: 80, modifiers: 4 });

export default {
  name: "Sample tutorial: every new block completes from its real event",
  input: "palette, new note, write, convert→Source, select, create Claim, open Claim, context, create .base, settings tab",
  expected: "each step advances only on its own event; ends on 'You're set up'",
  setup: async ({ client }) =>
    client.evaluate(`app.workspace.getLeavesOfType("discourse-context-view").forEach((l) => l.detach()); return true;`),
  run: async (ctx) => {
    const { client, json, vault, branch } = ctx;
    const pid = json(vault.pluginId);
    const seen = [];
    const log = async () => seen.push(await T(client));
    await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:play-sample-tutorial`)});`);
    await waitTitle(client, "Open the command palette"); await log();
    await cmdP(client);
    await waitTitle(client, "Start a paper note"); await log();
    await client.pressEscape();
    await client.evaluate(`return app.commands.executeCommandById("file-explorer:new-file");`);
    await waitTitle(client, "Write a finding"); await log();
    // Move the new note into _verify so the run doesn't litter the vault root.
    const path = `_verify/${branch}/Paper ${Date.now()}.md`;
    await client.evaluate(`return (async () => { const f = app.workspace.getActiveFile();
      await app.fileManager.renameFile(f, ${json(path)});
      const ed = app.workspace.activeEditor.editor; ed.setValue("Heat shock slows yeast growth.\\n"); ed.setCursor({ line: 0, ch: 0 }); ed.focus(); return true; })();`);
    await next(client);
    await waitTitle(client, "Make it a Source"); await log();
    const earlyAdvance = await client.evaluate(`return (async () => { const f = app.workspace.getActiveFile();
      await app.fileManager.processFrontMatter(f, (fm) => { fm.unrelated = 1; }); await new Promise((r) => setTimeout(r, 600));
      return document.querySelector(".dg-tutorial-card").firstElementChild.textContent; })();`);
    await client.evaluate(`return (async () => { const f = app.workspace.getActiveFile();
      const src = app.plugins.plugins[${pid}].settings.nodeTypes.find((t) => t.name === "Source");
      await app.fileManager.processFrontMatter(f, (fm) => { fm.nodeTypeId = src.id; }); return true; })();`);
    await waitTitle(client, "Select the finding"); await log();
    await client.evaluate(`app.workspace.activeEditor.editor.focus(); app.workspace.activeEditor.editor.setCursor({ line: 0, ch: 0 }); return true;`);
    await client.key({ key: "End", code: "End", windowsVirtualKeyCode: 35, nativeVirtualKeyCode: 35, modifiers: 8 });
    await waitTitle(client, "Capture it as a claim"); await log();
    const claimPath = `_verify/${branch}/CLM - yeast ${Date.now()}.md`;
    await client.evaluate(`return (async () => { const claim = app.plugins.plugins[${pid}].settings.nodeTypes.find((t) => t.name === "Claim");
      const f = await app.vault.create(${json(claimPath)}, ""); await app.fileManager.processFrontMatter(f, (fm) => { fm.nodeTypeId = claim.id; }); return true; })();`);
    await waitTitle(client, "Open your claim"); await log();
    await client.evaluate(`return (async () => { await app.workspace.getLeaf(false).openFile(app.vault.getAbstractFileByPath(${json(claimPath)})); return true; })();`);
    await waitTitle(client, "See the claim's context"); await log();
    await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:toggle-discourse-context`)});`);
    await waitTitle(client, "List all your claims"); await log();
    await client.evaluate(`return (async () => { await app.vault.create(${json(`_verify/${branch}/Claims ${Date.now()}.base`)}, ""); return true; })();`);
    await waitTitle(client, "Find your node types"); await log();
    await client.evaluate(`app.setting.open(); app.setting.openTabById(${pid}); return true;`);
    await waitTitle(client, "You're set up"); await log();
    await client.evaluate(`app.setting.close(); return true;`);
    return { seen, earlyAdvance };
  },
  expect: (a) => ({
    pass: a.seen.length === 11 && a.earlyAdvance === "Make it a Source",
    actual: `${a.seen.length}/11 steps reached; unrelated frontmatter edit left card on "${a.earlyAdvance}"`,
  }),
  teardown: async ({ client }) => client.evaluate(`[...document.querySelectorAll(".dg-tutorial-card button")].find((b) => b.textContent === "End tour" || b.textContent === "Finish")?.click(); return true;`),
};
